import{c as a,Q as n,j as t,m as s}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Cash Flow","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cashflow.md","filePath":"guide/cashflow.md","lastUpdated":null}'),o={name:"guide/cashflow.md"};function r(i,e,l,c,d,h){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="cash-flow" tabindex="-1">Cash Flow <a class="header-anchor" href="#cash-flow" aria-label="Permalink to &quot;Cash Flow&quot;">​</a></h1><p>When money is expected to arrive and leave, and what is safe to spend.</p><h2 id="safe-to-spend" tabindex="-1">Safe-to-spend <a class="header-anchor" href="#safe-to-spend" aria-label="Permalink to &quot;Safe-to-spend&quot;">​</a></h2><p>Safe-to-spend = current balance + scheduled income − scheduled expenses − reserve.</p><ul><li><strong>Scheduled</strong> comes from confirmed recurring items and planned transactions.</li><li><strong>Reserve</strong> is your emergency-fund buffer (or a manual cushion). The screen lets you tune it and see the effect live.</li><li>The figure is shown with segments: Today, Horizon, and Safe. Changing the horizon (7/14/30 days) re-slices the same calculation; no new data is fetched.</li></ul><p>Source: <code>finsight-core::forecast</code> + <code>finsight-core::cashflow</code>. Deterministic math; the Copilot explains the inputs when asked.</p><h2 id="calendar-events" tabindex="-1">Calendar &amp; events <a class="header-anchor" href="#calendar-events" aria-label="Permalink to &quot;Calendar &amp; events&quot;">​</a></h2><p>The calendar renders scheduled inflows/outflows by date. Each event shows merchant, amount, and source (recurring vs planned transaction). A row without a firm date is rendered as “around the 15th” with the tolerance noted.</p><h2 id="inputs-assumptions" tabindex="-1">Inputs &amp; assumptions <a class="header-anchor" href="#inputs-assumptions" aria-label="Permalink to &quot;Inputs &amp; assumptions&quot;">​</a></h2><p>The inspector lists:</p><ul><li>Definition of safe-to-spend</li><li>Inputs (balances, recurring, planned)</li><li>Exclusions (unconverted currencies, incomplete history)</li><li>Assumptions (cadence, reserve)</li><li>Period and data-quality warnings</li></ul><p>If the figure looks wrong, the inspector is the place to find out why — values come from the same metrics layer as every other screen.</p><h2 id="planned-transactions" tabindex="-1">Planned transactions <a class="header-anchor" href="#planned-transactions" aria-label="Permalink to &quot;Planned transactions&quot;">​</a></h2><p>Create a future transaction (e.g. quarterly tax) to model its effect without booking it yet. Planned items feed Cash Flow and Scenarios; they are not real transactions until you convert them.</p><p>See also: <a href="/FinSight/guide/recurring">Recurring</a>, <a href="/FinSight/guide/scenarios">Scenarios</a>.</p>',15)])])}const f=a(o,[["render",r]]);export{p as __pageData,f as default};
